// ─── NSN LOOKUP HELPERS ───────────────────────────────────────────────────────

const _nsnIndex = new Map(MASTER_NSN_DB.map(r=>[r.nsn, r]));
const _fscIndex = MASTER_NSN_DB.reduce((m,r)=>{ (m[r.fsc]||(m[r.fsc]=[])).push(r); return m; },{});

function nsnLookup(nsn){
  const n = nsn.replace(/[^0-9]/g,'').replace(/^(\d{4})(\d{2})(\d{3})(\d{4})$/,'$1-$2-$3-$4');
  return _nsnIndex.get(n)||null;
}
function nsnByFSC(fsc){ return _fscIndex[fsc]||[]; }
function nsnSearch(q){
  const qq=q.toLowerCase();
  return MASTER_NSN_DB.filter(r=>
    r.nsn.includes(q) ||
    (r.item&&r.item.toLowerCase().includes(qq)) ||
    (r.part_numbers&&r.part_numbers.some(p=>p.toLowerCase().includes(qq)))
  ).slice(0,50);
}
function cageLookup(c){ return MASTER_CAGE_DB.find(r=>r.cage===c)||null; }

// Expose globally
window.SCC_NSN = { nsnLookup, nsnByFSC, nsnSearch, cageLookup, MASTER_NSN_DB, MASTER_CAGE_DB };
